-- identifier_schemes: 4. The identifiers the country issues; a value of identifiers or meters matches the pattern.
insert into identifier_schemes (code, name, description, pattern, url_template, source_code, icd, published_by) values
  ('codice_catastale_comune', 'Codice catastale del comune', 'The four-character code the cadastre and the tax code (codice fiscale) give a municipality: a letter and three digits. A parcel of the cadastre is named within its municipality by its sheet (foglio), parcel (particella) and unit (subalterno), which no scheme of this pack holds yet.', '^[A-Z][0-9]{3}$', null, 'agenzia_entrate_catasto', null, 'pack:it'),
  ('istat', 'Codice ISTAT del comune', 'The six-digit statistical code of a municipality in the statistics office''s list of territorial administrative units: three digits of the province (or metropolitan city or equivalent unit) and three of the municipality within it, with its leading zeros. It is not the postal code (CAP) nor the cadastral code.', '^[0-9]{6}$', null, 'istat_municipalities', null, 'pack:it'),
  ('partita_iva', 'Partita IVA', 'The VAT number of a business or another taxable person: eleven digits, seven of the person, three of the tax office, and a check digit. No check digit is validated here.', '^[0-9]{11}$', null, null, '0211', 'pack:it'),
  ('pod', 'POD', 'The code of a withdrawal point (punto di prelievo) of the Italian electricity grid, issued by the distribution operator the point is connected to: IT, three digits of that operator, the letter E for electricity, and the number of the point, eight digits on most bills, nine on some. It stays the same through a change of retailer, a transfer or a takeover of the supply. The register of the operators'' three-digit codes was not read: the pattern follows the structure the operators print on their bills.', '^IT[0-9]{3}E[0-9]{8,9}$', null, null, null, 'pack:it')
on conflict (code) do update set
